/* eslint-disable max-len */
/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isAsci = require( '@stdlib/assert/is-ascii' );
var format = require( '@stdlib/string/format' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isNonNegativeNumber = require( '@stdlib/assert/is-nonnegative-number' );
var isString = require( '@stdlib/assert/is-string' );
var isBoolean = require( '@stdlib/assert/is-boolean' );
var isValidBackgroundColor = require( './utils/is-valid-background-color.js' );
var isValidForegroundColor = require( './utils/is-valid-foreground-color.js' );


// FUNCTIONS //

/**
* Method which return the default option.
*
* @private
* @name defaults
* @returns {Object} - out
*/
function defaults( ) {
	var out = {};

	out.row = 0;
	out.column = 0;
	out.value = '';
	out.overwrite = false;
	out.safeArea = false;
	out.foregroundColor = void 0;
	out.backgroundColor = void 0;
	return out;
}

/**
* Method to validate the object.
*
* @private
* @name validate
* @param {Object} opts - destination object
* @param {Object} options - function options
* @returns {Object} - out
*/
function validate( opts, options ) {
	if ( !isPlainObject( options ) ) {
		return new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}

	if ( hasOwnProp( options, 'row' ) ) {
		opts.row = options.row;
		if ( !isNonNegativeNumber( options.row ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a non-negative-number. Option: `%s`.', 'height', options.row ) );
		}
	}
	else {
		return new TypeError( format( 'invalid option. `%s` property is expected: `%s`.', 'row', options.row ) );
	}

	if ( hasOwnProp( options, 'column' ) ) {
		opts.column = options.column;
		if ( !isNonNegativeNumber( options.column ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a non-negative-number. Option: `%s`.', 'height', options.column ) );
		}
	}
	else {
		return new TypeError( format( 'invalid option. `%s` property is expected: `%s`.', 'column', options.column ) );
	}

	if ( hasOwnProp( options, 'value' ) ) {
		opts.value = options.value;
		if ( !isString( options.value ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a string. Option: `%s`.', 'value', options.value ) );
		}
	}
	else {
		return new TypeError( format( 'invalid option. `%s` property is expected: `%s`.', 'value', options.value ) );
	}

	if ( hasOwnProp( options, 'overwrite' ) ) {
		opts.overwrite = options.overwrite;
		if ( !isBoolean( options.overwrite ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a boolean. Option: `%s`.', 'overwrite', options.overwrite ) );
		}
	}
	if ( hasOwnProp( options, 'safeArea' ) ) {
		opts.safeArea = options.safeArea;
		if ( !isBoolean( options.safeArea ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a boolean. Option: `%s`.', 'safeArea', options.safeArea ) );
		}
	}
	if ( hasOwnProp( options, 'backgroundColor' ) ) {
		opts.backgroundColor = options.backgroundColor;
		if ( !isString( options.backgroundColor ) || !isValidBackgroundColor( options.backgroundColor ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a string and a valid background color code. Option: `%s`.', 'backgroundColor', options.backgroundColor ) );
		}
	}
	if ( hasOwnProp( options, 'foregroundColor' ) ) {
		opts.foregroundColor = options.foregroundColor;
		if ( !isString( options.foregroundColor ) || !isValidForegroundColor( options.foregroundColor ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a string and a valid foreground color code. Option: `%s`.', 'foregroundColor', options.foregroundColor ) );
		}
	}
}


// MAIN //

/**
* Add string.
*
* @private
* @name addString
* @param {Options} options - options
* @param {number} [options.row] - row number of start position
* @param {number} [options.column] - row number of start position
* @param {string} [options.value] - string value
* @param {boolean} [options.overwrite] - overwrite
* @param {boolean} [options.safeArea] - weather to put coordinates in safe area or not
* @param {string} [options.forgroundColor] - forgroundColor to use
* @param {string} [options.backgroundColor] - foregroundColor to use
* @throws {Error} must provide valid options
* @returns {void}
*/
function addString( options ) {
	var opts;
	var err;
	var chr;
	var r;
	var c;
	var i;

	opts = defaults();
	if ( arguments.length ) {
		err = validate( opts, options );
		if ( err ) {
			throw err;
		}
	}
	else {
		return new TypeError( format( 'invalid option. `%s` options object is expected', 'addString' ) );
	}
	r = opts.row;
	c = opts.column;
	for ( i = 0; i < opts.value.length; i++ ) {
		chr = opts.value[ i ];
		if ( isAsci( chr ) ) {
			this.setGlyph( r, c, 'asci' + chr.charCodeAt( 0 ), opts.overwrite, opts.safeArea );
		}
		if ( opts.foregroundColor ) {
			this.setForegroundColor( r, c, opts.foregroundColor, opts.overwrite, opts.safeArea );
		}
		if ( opts.backgroundColor ) {
			this.setBackgroundColor( r, c, opts.backgroundColor, opts.overwrite, opts.safeArea );
		}
		c+=1;
	}
	if ( !this._quite ) {
		this.emit( 'change' );
	}
}

module.exports = addString;
